<script lang="ts">
	import { readPrivateFeed, privateFeedIdentity } from "$platform/private-feed";
	let privateSearchGeneration = 0;
	$effect(() => { $privateFeedIdentity; privateSearchGeneration++; feed = undefined; });
	import { replaceState } from "$app/navigation";
	import { page } from "$app/state";
	import { PUBLIC_SITE_NAME } from "$env/static/public";
	import { Constants } from "$lib";
	import API from "$lib/API";
	import GenericPagination from "$lib/components/GenericPagination.svelte";
	import ReportSearch from "$lib/components/ReportSearch.svelte";
	import ReportSearchFilter from "$lib/components/ReportSearchFilter.svelte";
	import { StatusCodes } from "http-status-codes";

	let feed = $state<ReportFeedResponse>();
	const onSearch = async () => {
		const generation = ++privateSearchGeneration, identity = $privateFeedIdentity;
		feed = undefined;
		const { href } = window.location;
		const q = new URLSearchParams(window.location.search);
		q.set("limit", "36");

		const res = await readPrivateFeed<ReportFeedResponse>("/report", q);
		if (generation !== privateSearchGeneration || identity !== $privateFeedIdentity || window.location.href !== href) {
			return;
		}

		if (res?.status === StatusCodes.OK && res.body) {
			feed = res.body;
			const { _$ReportSearch_feed: discardedPrivateCache, ...safeState } = page.state as Record<string, unknown>;
			replaceState(window.location.href, safeState);
		} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
			throw Constants.Error.TooManyRequests;
		} else throw Constants.Error.Unknown;
	};
</script>

<svelte:head>
	{#if feed && feed.page > 1}
		<title>My Reports - Page {feed.page} - {PUBLIC_SITE_NAME}</title>
	{:else}
		<title>My Reports - {PUBLIC_SITE_NAME}</title>
	{/if}
</svelte:head>

<section class="flex flex-auto flex-col space-y-5">
	<header class="space-y-5">
		<h2 class="text-xl font-medium">My Reports</h2>
		{#key page.url.search}
			<ReportSearchFilter bind:feed />
		{/key}
	</header>
	{#key page.url.search}
		<ReportSearch bind:feed {onSearch} />
	{/key}
	{#if feed && feed.total > feed.limit}
		<footer>
			<GenericPagination {feed} />
		</footer>
	{/if}
</section>
